let lifeData=null;const lifeKinds={wood_border:'Деревянные бортики',concrete_border:'Бетонный бордюр',trellis:'Установить шпалеру',drip:'Капельный полив',mulch:'Мульчирование',cover:'Временное укрытие',soil:'Проверка почвы',inspect:'Осмотр садовником',photo:'Фотоотчёт',timelapse:'Таймлапс',archive:'Облачный архив камеры',seedlings:'Посадить рассаду',kit:'Готовый набор посадок',ripeness:'Выбрать спелость при сборе',regular:'Регулярные осмотры',autocare:'План автоматического ухода'};
const lifeStatus={requested:'Новая заявка',confirmed:'Согласована',shipped:'Передана в доставку',delivered:'Получена',cancelled:'Отменена',reviewed:'Рассмотрена',done:'Выполнена',ready:'Пора собрать',collected:'Собрано',disposed:'Утилизация подтверждена'};
const hasStorage=()=>lifeData?.memberships.some(m=>m.kind==='storage'&&new Date(m.expires_at)>new Date());
async function loadLife(){if(!account)return;try{const uid=account.id;const [life,batches]=await Promise.all([api('lifecycle'),api('batches')]);if(account?.id!==uid)return;lifeData=life;batchData=batches.batches;render()}catch(e){toast(e.message)}}
async function lifeAction(route,body){await api('life-'+route,body);await loadLife()}
function subscribeLife(kind){const key=crypto.randomUUID(),price=kind==='storage'?400:1100;formAsync('Тестовая подписка',`<h3>${kind==='storage'?'Склад':'Автоматический уход'} · ${price} демо-₽ / календарный месяц</h3><p>Разовая покупка месяца, без автоматического продления. Продление добавляет месяц к оставшемуся сроку.</p><p class="note">Это имитация оплаты. ${kind==='storage'?'Кладовая или холодильник назначаются при приёмке партии. Вместимость и физическое размещение согласуются с фермой.':'Цена предварительная. План и перечень включённых работ согласует садовник; подписка сама не включает оборудование и не запускает физические работы.'}</p><button class="btn">Подключить за ${price} демо-₽</button>`,async()=>{await lifeAction('subscribe',{kind,key});walletData=null})}
function lifecyclePage(){if(!account)return heading('Урожай, склад и доставка.','Войдите, чтобы управлять урожаем.')+'<button class="btn" onclick="profile()">Войти</button>';if(!lifeData)return '<p>Загружаем хозяйство…</p>';const d=lifeData;return heading('С грядки — на ваш стол.','Сроки сбора, хранение, корзины и забота о посадках.')+`<div class="grid"><section class="panel"><h3>Склад · 400 демо-₽/месяц</h3><p>Кладовая и холодильник. ${hasStorage()?'Подписка активна.':'Без склада урожай доступен только для оформления доставки, подарка или благотворительной корзины.'}</p><button class="btn" onclick="subscribeLife('storage')">${hasStorage()?'Продлить':'Подключить'} склад</button></section><section class="panel"><h3>Автоуход · 1 100 демо-₽/месяц</h3><p>По согласованному плану. Подключение тестовое; реальные работы подтверждает ферма.</p><button class="btn" onclick="subscribeLife('autocare')">Подключить / продлить</button></section></div><p class="note">${d.memberships.map(m=>`${m.kind==='storage'?'Склад':'Автоуход'}: до ${fmt(m.expires_at)}`).join(' · ')||'Подписок пока нет'}</p><div class="actions"><button class="btn" onclick="basketForm()">Собрать корзину домой / в подарок</button><button class="btn light" onclick="lifeRequest()">Заказать улучшение или уход</button><button class="btn light" onclick="zoneForm()">Разделить грядку на зоны</button><button class="btn light" onclick="lifePrefs()">Отпуск и бюджет</button><a class="btn light" href="#warehouse">Партии и паспорта</a></div><section class="panel"><h2>Пора собирать</h2>${d.windows.map(w=>`<div class="event"><b>${esc(w.crop)} · грядка №${w.plot_id}</b><p class="${w.status==='ready'?'harvest-alert':''}">${lifeStatus[w.status]} · до ${fmt(w.collect_by)} ${w.status==='ready'&&new Date(w.collect_by)<new Date()?'· Срок прошёл: нужен осмотр':''}</p><p>${esc(w.notes)}</p>${w.status==='ready'?`<button class="btn light" onclick="lifeRequest('ripeness',${w.plot_id})">Заказать сбор</button>`:''}${account.role==='admin'&&w.status==='ready'?`<button class="btn light" onclick="closeWindow('${w.id}')">Подтвердить сбор / утилизацию</button>`:''}</div>`).join('')||'<p>Садовник отметит созревание и срок сбора после осмотра.</p>'}<p class="note">Напоминания в «Событиях» — раз в день до решения. Внешние push/SMS не подключены. Просрочка требует осмотра, а не автоматического выбрасывания.</p></section><section class="panel"><h2>Урожай к отправке ${hasStorage()?'и продаже':'· без длительного хранения'}</h2>${batchData.map(b=>`<div class="event"><h3>${esc(b.crop)} · ${(b.balance_grams-b.reserved_grams)/1000} кг свободно</h3><p>${b.verified?'Приёмка подтверждена':'Ожидает приёмки'} · ${b.expires_at?'Срок: '+fmt(b.expires_at):'Срок ещё не установлен'}</p><p>${esc(b.storage_conditions||'Условия определит сотрудник при приёмке')}</p>${b.expires_at&&new Date(b.expires_at)<new Date()?'<p class="harvest-alert">Выдача и продажа заблокированы. Нужен осмотр и решение сотрудника.</p>':''}${hasStorage()?`<button class="btn light" onclick="produceListing('${b.id}')">Выставить на маркет</button>`:''}<button class="btn light" onclick="showPassport('${b.id}')">Паспорт</button></div>`).join('')||'<p>Пока нет партий урожая.</p>'}</section><section class="panel"><h2>Мои корзины</h2>${d.deliveries.map(o=>`<div class="event"><b>${({home:'Домой',gift:'Подарок',charity:'Благотворительность'})[o.kind]} · ${esc(o.recipient)}</b><p>${esc(o.address)} · ${lifeStatus[o.status]}</p><p>Контакт: ${esc(o.contact)}</p><p>${(o.items||[]).map(i=>esc(i.crop)+' · '+i.grams/1000+' кг').join('; ')}</p><p>${esc(o.message||'')}</p>${['requested','confirmed'].includes(o.status)?`<button class="btn light" onclick="changeDelivery('${o.id}','cancelled')">Отменить и освободить резерв</button>`:''}${account.role==='admin'?({requested:`<button class="btn" onclick="changeDelivery('${o.id}','confirmed')">Подтвердить согласование</button>`,confirmed:`<button class="btn" onclick="changeDelivery('${o.id}','shipped')">Подтвердить фактическую отправку</button>`,shipped:`<button class="btn" onclick="changeDelivery('${o.id}','delivered')">Подтвердить получение</button>`}[o.status]||''):''}</div>`).join('')||'<p>Корзин пока нет.</p>'}<p class="note">Оформление создаёт заявку и резерв урожая. Стоимость, время и возможность доставки согласует ферма; курьер автоматически не вызывается.</p></section><section class="panel"><h2>Доска благотворительности</h2>${d.charities.map(c=>`<div class="event"><h3>${esc(c.name)}</h3><p>${esc(c.description)}</p><button class="btn light" onclick="basketForm('charity','${c.id}')">Подготовить корзину</button></div>`).join('')||'<p>Проверенных получателей пока нет. Управляющий добавит организации и семьи после согласования условий приёма. Данные детей здесь не публикуются.</p>'}</section><section class="panel"><h2>Зоны посадок</h2>${d.zones.map(z=>`<div class="event">№${z.plot_id} · ${esc(z.name)} · ${Number(z.area)} м² · ${esc(z.crop)}</div>`).join('')||'<p>Можно разделить свою грядку на несколько зон.</p>'}<h2>Заявки на уход и оборудование</h2>${d.requests.map(r=>`<div class="event"><b>${lifeKinds[r.kind]} · №${r.plot_id}</b><p>${esc(r.details)} · ${lifeStatus[r.status]}</p><p>${esc(r.report||'Цена и сроки будут согласованы до выполнения.')}</p>${account.role==='admin'?`<button class="btn light" onclick="reviewLifeRequest('${r.id}')">Ответить</button>`:''}</div>`).join('')||'<p>Заявок пока нет.</p>'}</section><section class="panel"><h2>Мои объявления</h2>${d.myListings.map(l=>`<div class="event">${esc(l.crop)} · ${l.grams/1000} кг · ${money(l.price_kopecks)} за весь лот <button class="btn light" onclick="cancelProduceListing('${l.id}')">Снять и освободить урожай</button></div>`).join('')||'Объявлений пока нет.'}</section>${account.role==='admin'?lifeAdmin():''}`}
function basketForm(kind='home',charity=''){const eligible=batchData.filter(b=>b.verified&&new Date(b.expires_at)>new Date()&&b.balance_grams>b.reserved_grams);if(!eligible.length){toast('Нужны принятые партии с действующим сроком хранения');return}const key=crypto.randomUUID(),c=lifeData.charities.find(c=>c.id===charity);formAsync('Собрать корзину',`<label>Назначение<select name="kind">${[['home','Домой'],['gift','В подарок'],['charity','Благотворительность']].map(([k,t])=>`<option value="${k}" ${kind===k?'selected':''}>${t}</option>`).join('')}</select></label>${eligible.map(b=>`<label>${esc(b.crop)} · доступно ${(b.balance_grams-b.reserved_grams)/1000} кг<input type="number" name="batch_${b.id}" min="0" step="0.001" max="${(b.balance_grams-b.reserved_grams)/1000}" value="0"></label>`).join('')}<label>Получатель<input name="recipient" required maxlength="120" value="${esc(c?.name||'')}"></label><label>Адрес<input name="address" required minlength="5" maxlength="500"></label><label>Телефон или контакт<input name="contact" required minlength="5" maxlength="100"></label><label>Пожелания, время, открытка<textarea name="message" maxlength="1000"></textarea></label><p class="note">Создаётся заявка на согласование, без списания стоимости доставки.</p><button class="btn">Оформить корзину и зарезервировать урожай</button>`,async f=>lifeAction('delivery',{...Object.fromEntries(f),key,items:eligible.map(b=>({id:b.id,grams:Math.round(Number(f.get('batch_'+b.id))*1000)})).filter(i=>i.grams>0)}))}
async function changeDelivery(id,status){try{await lifeAction('delivery-update',{id,status})}catch(e){toast(e.message)}}
function lifeRequest(kind='inspect',plot){formAsync('Заявка садовнику',`<label>Грядка<select name="plot">${plotOptions()}</select></label><label>Опция<select name="kind">${Object.entries(lifeKinds).map(([k,t])=>`<option value="${k}" ${k===kind?'selected':''}>${t}</option>`).join('')}</select></label><label>Набор посадок, если нужен<select name="kit"><option>Не выбран</option><option>Салат: томаты, огурцы, зелень</option><option>Зелень к завтраку: салат, укроп, базилик</option><option>Острый огород: перец и пряные травы</option></select></label><label>Подробности<textarea name="details" minlength="5" maxlength="800" required placeholder="Например: рассада вместо семян; урожай для перевозки; архив за 7 дней"></textarea></label><p class="note">Фермер проверит совместимость, оборудование, цену и срок. Архив и таймлапс доступны только после подключения записи камер; заявка не включает запись автоматически.</p><button class="btn">Отправить на согласование</button>`,async f=>lifeAction('request',{plot:Number(f.get('plot')),kind:f.get('kind'),details:f.get('details')+' · Набор: '+f.get('kit')}));if(plot)document.querySelector('#fields select[name=plot]').value=String(plot)}
function zoneForm(){formAsync('Новая зона посадок',`<label>Грядка<select name="plot">${plotOptions()}</select></label><label>Название<input name="name" required maxlength="80"></label><label>Культура<input name="crop" required maxlength="100"></label><label>Площадь, м²<input name="area" type="number" min="0.1" step="0.1" required></label><button class="btn">Добавить зону</button>`,async f=>lifeAction('zone',{...Object.fromEntries(f),plot:Number(f.get('plot')),area:Number(f.get('area'))}))}
function lifePrefs(){const p=lifeData.preferences;formAsync('Отпуск и бюджет',`<label>Предел деморасходов в календарный месяц, ₽ · 0 без лимита<input name="limit" type="number" min="0" max="1000000" value="${(p.monthly_limit||0)/100}" required></label><label>Отпуск с<input name="start" type="date" value="${p.vacation_start?String(p.vacation_start).slice(0,10):''}"></label><label>По<input name="end" type="date" value="${p.vacation_end?String(p.vacation_end).slice(0,10):''}"></label><label>Разрешённые работы и пожелания<textarea name="notes" maxlength="1000">${esc(p.notes||'')}</textarea></label><p class="note">Лимит применяется к новым демооплатам работ и подписок; возвраты не освобождают месячный лимит. План отпуска согласуется с садовником, автоматическое исполнение ещё не подключено.</p><button class="btn">Сохранить</button>`,async f=>lifeAction('preferences',{...Object.fromEntries(f),limit:Math.round(Number(f.get('limit'))*100)}))}
function produceListing(batch){formAsync('Продать урожай со склада','<label>Количество, кг<input name="kg" type="number" min="0.001" step="0.001" required></label><label>Цена за весь лот, ₽<input name="price" type="number" min="1" max="1000000" required></label><p>Объём резервируется. Объявление скрывается после истечения срока хранения или подписки склада. Покупка согласуется через ферму.</p><button class="btn">Опубликовать</button>',async f=>lifeAction('listing',{batch,grams:Math.round(Number(f.get('kg'))*1000),price:Math.round(Number(f.get('price'))*100)}))}
async function cancelProduceListing(id){try{await lifeAction('listing-cancel',{id})}catch(e){toast(e.message)}}
function lifeAdmin(){return `<section class="panel"><h2>Управляющему: приёмка и сроки</h2><div class="actions"><button class="btn" onclick="windowForm()">Отметить созревание</button><button class="btn light" onclick="charityForm()">Добавить получателя помощи</button></div>${lifeData.reviewBatches.map(b=>`<div class="event">${esc(b.crop)} · грядка №${b.plot_id} · ${b.balance_grams/1000} кг <button class="btn light" onclick="verifyBatch('${b.id}')">Условия и срок хранения</button><button class="btn light" onclick="disposeBatch('${b.id}')">Подтвердить утилизацию</button></div>`).join('')}<p class="note">Сроки назначаются по культуре, спелости, температуре и осмотру. <a href="https://extension.umn.edu/garden-and-home/yard-and-garden/gardening-in-minnesota/harvesting-and-storing-home-garden-vegetables" target="_blank" rel="noopener">Рекомендации по хранению овощей</a>. Кладовая и холодильник не взаимозаменяемы для всех культур.</p></section>`}
function windowForm(){formAsync('Урожай созрел','<label>Номер грядки<input name="plot" type="number" min="1" required></label><label>Культура<input name="crop" required maxlength="100"></label><label>Собрать до<input name="deadline" type="datetime-local" required></label><label>Результат осмотра<textarea name="notes" required></textarea></label><button class="btn">Установить срок и уведомить</button>',async f=>lifeAction('window',{...Object.fromEntries(f),plot:Number(f.get('plot')),deadline:new Date(f.get('deadline')).toISOString()}))}
function closeWindow(id){formAsync('Подтверждение фактического результата','<label>Результат<select name="status"><option value="collected">Собрано · партию записать отдельно</option><option value="disposed">Фактически утилизировано</option></select></label><label>Отчёт<textarea name="notes" minlength="10" required></textarea></label><button class="btn">Подтвердить факт</button>',async f=>lifeAction('window-close',{id,...Object.fromEntries(f)}))}
function verifyBatch(id){formAsync('Приёмка и хранение','<label>Место<select name="storage"><option value="pantry">Кладовая</option><option value="fridge">Холодильник</option></select></label><label>Годен к выдаче до<input name="expires" type="datetime-local" required></label><label>Состояние, температура, условия<textarea name="conditions" minlength="10" required></textarea></label><button class="btn">Подтвердить приёмку</button>',async f=>lifeAction('batch-verify',{id,...Object.fromEntries(f),expires:new Date(f.get('expires')).toISOString()}))}
function charityForm(){formAsync('Проверенный получатель помощи','<label>Публичное название<input name="name" required maxlength="120"></label><label>Какие продукты принимает, условия передачи<textarea name="description" minlength="10" required></textarea></label><p>Публикуйте только согласованное название и условия, без личных данных детей или семей.</p><button class="btn">Добавить на доску</button>',async f=>lifeAction('charity',Object.fromEntries(f)))}
function reviewLifeRequest(id){formAsync('Ответ на заявку','<label>Статус<select name="status"><option value="reviewed">Рассмотрена</option><option value="done">Выполнена</option><option value="cancelled">Отменена</option></select></label><label>Ответ: условия, цена, сроки или результат<textarea name="report" minlength="10" required></textarea></label><button class="btn">Сохранить</button>',async f=>lifeAction('request-review',{id,...Object.fromEntries(f)}))}
const beforeLifeRender=render;render=function(){beforeLifeRender();const r=location.hash.slice(1);if(['lifecycle','delivery'].includes(r)){$('#app').innerHTML=lifecyclePage();$('#crumb').textContent='УРОЖАЙ И ДОСТАВКА'}if(account&&!(r==='home'&&!myPlots().length)&&['home','warehouse','harvest','market','settings','lifecycle','delivery'].includes(r))$('#app').insertAdjacentHTML('afterbegin','<div class="context-tabs"><a href="#lifecycle">Урожай · склад · доставка · уход</a></div>');if(r==='market'&&lifeData){$('#app').innerHTML=heading('Маркет урожая','Только принятые партии с действующим сроком хранения и активным складом.')+`<a class="btn" href="#lifecycle">Продать со склада</a><div class="grid">${lifeData.listings.map(l=>`<div class="panel"><h3>${esc(l.crop)}</h3><p>${l.grams/1000} кг · ${money(l.price_kopecks)} за лот</p><p>Срок: ${fmt(l.expires_at)}</p><small>Покупка за демосредства; доставка отдельно.</small>${l.owner_id!==account?.id?`<button class="btn" onclick="buyProduce('${l.id}')">Купить демосредствами</button>`:''}</div>`).join('')||'<p>Доступных партий пока нет.</p>'}</div>`}};
addEventListener('hashchange',()=>{if(['#lifecycle','#delivery','#market'].includes(location.hash))loadLife()});const refreshBeforeLife=refreshCloud;refreshCloud=async function(){await refreshBeforeLife();if(['#lifecycle','#delivery','#market'].includes(location.hash))await loadLife()};render();

function disposeBatch(id){formAsync('Фактическая утилизация','<p>Подтверждайте только после выполнения. Вся свободная партия будет списана; активные резервы нужно сначала отменить.</p><label>Отчёт<textarea name="reason" minlength="10" required></textarea></label><button class="btn">Подтвердить списание</button>',async f=>lifeAction('dispose',{id,reason:f.get('reason')}))}
